import time

import pytest
import requests

SANDBOX = "https://sandbox.payments.example/v1/charges"
# Sandbox rate-limits at 5 req/s; space calls a bit over 1/5 s apart.
SANDBOX_CALL_INTERVAL = 0.25


@pytest.mark.integration
def test_charges_roundtrip():
    for i, amount in enumerate((100, 250, 999, 1200)):
        if i:
            time.sleep(SANDBOX_CALL_INTERVAL)
        resp = requests.post(SANDBOX, json={"amount_cents": amount}, timeout=10)

